"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[5864],{1615(n,e,t){t.r(e),t.d(e,{assets:()=>g,contentTitle:()=>d,default:()=>h,frontMatter:()=>l,metadata:()=>i,toc:()=>c});const i=JSON.parse('{"id":"part4-ml-foundations/trees-bagging-boosting","title":"Bagging & Boosting (AdaBoost + XGBoost) \u2014 Trees, Impurities, and How Splits Work","description":"This page is a complete, friendly walkthrough of what we discussed: how decision trees split using Gini impurity and Information Gain, how Bagging (Random Forests) works, how Boosting works, a deep step-by-step of Ada...","source":"@site/docs/part4-ml-foundations/05-trees-bagging-boosting.mdx","sourceDirName":"part4-ml-foundations","slug":"/part4-ml-foundations/05-trees-bagging-boosting","permalink":"/tutorials/part4-ml-foundations/05-trees-bagging-boosting","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":5,"frontMatter":{"title":"Bagging & Boosting (AdaBoost + XGBoost) \u2014 Trees, Impurities, and How Splits Work","slug":"/part4-ml-foundations/05-trees-bagging-boosting","description":"This page is a complete, friendly walkthrough of what we discussed: how decision trees split using Gini impurity and Information Gain, how Bagging (Random Forests) works, how Boosting works, a deep step-by-step of Ada...","sidebar_label":"5. Trees, bagging, and boosting","pagination_label":"5. Trees, bagging, and boosting","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"4. Linear classification","permalink":"/tutorials/part4-ml-foundations/04-linear-classification"},"next":{"title":"Part overview","permalink":"/tutorials/part5-deep-learning-and-llms/overview"}}');var s=t(4848),a=t(8453),o=t(8172);const r=JSON.parse('{"sourcePath":"part4-ml-foundations/05-trees-bagging-boosting.html","route":"/part4-ml-foundations/05-trees-bagging-boosting","kind":"chapter","partId":"part4","partLabel":"Part IV - Machine Learning Foundations","accent":"amber","heading":"Bagging & Boosting (AdaBoost + XGBoost)with Decision Tree Splits & Impurities","title":"Bagging & Boosting (AdaBoost + XGBoost) \u2014 Trees, Impurities, and How Splits Work","description":"This page is a complete, friendly walkthrough of what we discussed: how decision trees split using Gini impurity and Information Gain, how Bagging (Random Forests) works, how Boosting works, a deep step-by-step of Ada...","readingMinutes":10,"bodyClass":"","normalizeMath":false,"toc":[{"id":"1-what-is-an-ensemble-big-picture","label":"1) What is an Ensemble? Big Picture"},{"id":"2-decision-trees-how-they-learn-foundation","label":"2) Decision Trees: How They Learn Foundation"},{"id":"3-impurity-measures-gini-and-information-gain-splitting-criteria","label":"3) Impurity Measures: Gini and Information Gain Splitting Criteria"},{"id":"4-a-concrete-split-example-step-by-step-intuition","label":"4) A Concrete Split Example (Step-by-Step) Intuition"},{"id":"5-bagging-and-random-forests-variance-reduction","label":"5) Bagging and Random Forests Variance Reduction"},{"id":"6-boosting-overview-bias-reduction","label":"6) Boosting Overview Bias Reduction"},{"id":"7-adaboost-adaptive-boosting-deep-dive-weights-weak-learners","label":"7) AdaBoost (Adaptive Boosting) \u2014 Deep Dive Weights + Weak Learners"},{"id":"8-gradient-boosting-and-xgboost-loss-optimization","label":"8) Gradient Boosting and XGBoost Loss Optimization"},{"id":"9-sequential-vs-parallel-in-boosting-xgboost-important-detail","label":"9) Sequential vs Parallel in Boosting (XGBoost) Important Detail"},{"id":"10-random-forest-vs-xgboost-practical-comparison","label":"10) Random Forest vs XGBoost Practical Comparison"},{"id":"11-quick-cheat-sheet-remember-fast","label":"11) Quick Cheat Sheet Remember Fast"}],"html":"<div class=\\"wrap\\">\\n    <header class=\\"hero\\" id=\\"top\\">\\n      <div class=\\"hero-inner\\">\\n        <div class=\\"kicker\\">\\n          <span class=\\"pill\\"><span class=\\"dot\\"></span> One-page tutorial</span>\\n          <span class=\\"pill\\"><span class=\\"dot\\" style=\\"background:var(--green); box-shadow:0 0 0 4px rgba(5,150,105,0.14)\\"></span> Trees \u2192 Ensembles</span>\\n          <span class=\\"pill\\"><span class=\\"dot\\" style=\\"background:var(--amber); box-shadow:0 0 0 4px rgba(245,158,11,0.16)\\"></span> Impurities explained</span>\\n        </div>\\n        \\n        <p class=\\"sub\\">\\n          This page is a complete, friendly walkthrough of what we discussed:\\n          how decision trees split using <strong>Gini impurity</strong> and <strong>Information Gain</strong>,\\n          how <strong>Bagging</strong> (Random Forests) works, how <strong>Boosting</strong> works,\\n          a deep step-by-step of <strong>AdaBoost</strong>, and what makes <strong>XGBoost</strong> fast and powerful \u2014\\n          including what\u2019s <em>sequential</em> vs what can be <em>parallelized</em>.\\n        </p>\\n        <nav class=\\"toc\\">\\n          <a href=\\"#ensembles\\">Ensembles</a>\\n          <a href=\\"#trees\\">Decision Trees</a>\\n          <a href=\\"#impurity\\">Gini &amp; Information Gain</a>\\n          <a href=\\"#split-example\\">A Split Example</a>\\n          <a href=\\"#bagging\\">Bagging &amp; Random Forest</a>\\n          <a href=\\"#boosting\\">Boosting Overview</a>\\n          <a href=\\"#adaboost\\">AdaBoost Deep Dive</a>\\n          <a href=\\"#xgboost\\">Gradient Boosting &amp; XGBoost</a>\\n          <a href=\\"#parallel\\">Sequential vs Parallel</a>\\n          <a href=\\"#compare\\">Random Forest vs XGBoost</a>\\n          <a href=\\"#cheatsheet\\">Cheat Sheet</a>\\n        </nav>\\n      </div>\\n    </header>\\n\\n    \x3c!-- 1) Ensembles --\x3e\\n    <section id=\\"ensembles\\">\\n      <h2 id=\\"1-what-is-an-ensemble-big-picture\\">1) What is an Ensemble? <span class=\\"tag\\">Big Picture</span></h2>\\n\\n      <div class=\\"callout\\">\\n        <strong>Ensemble learning</strong> means we combine many simple models to create one strong model.\\n        The individual models are called <strong>base learners</strong> (often decision trees).\\n      </div>\\n\\n      <div class=\\"grid cols2\\">\\n        <div class=\\"card\\">\\n          <h3 id=\\"why-does-combining-models-help\\">Why does combining models help?</h3>\\n          <ul>\\n            <li><strong>Reduce variance</strong>: if one model is \u201cnoisy\u201d, averaging many models smooths errors.</li>\\n            <li><strong>Reduce bias</strong>: if one model is \u201ctoo simple\u201d, sequential correction can capture complex patterns.</li>\\n            <li><strong>Stability</strong>: ensembles are less sensitive to small changes in data.</li>\\n          </ul>\\n        </div>\\n\\n        <div class=\\"card\\">\\n          <h3 id=\\"the-two-main-families\\">The two main families</h3>\\n          <p><span class=\\"badge\\"><span class=\\"b\\"></span>Bagging</span> builds many models independently and averages/votes.</p>\\n          <p><span class=\\"badge\\"><span class=\\"g g\\"></span>Boosting</span> builds models sequentially, each correcting earlier mistakes.</p>\\n          <p class=\\"callout amber\\" style=\\"margin-top:10px\\">\\n            <strong>Key theme:</strong> Bagging focuses on <strong>variance reduction</strong>. Boosting focuses on <strong>bias reduction</strong> (and can also reduce variance with regularization).\\n          </p>\\n        </div>\\n      </div>\\n\\n      <div class=\\"mini-diagram\\" aria-label=\\"Bagging vs Boosting diagram\\">\\n        <svg viewBox=\\"0 0 980 210\\" role=\\"img\\">\\n          <defs>\\n            <linearGradient id=\\"g1\\" x1=\\"0\\" x2=\\"1\\">\\n              <stop offset=\\"0\\" stop-color=\\"rgba(37,99,235,0.18)\\"></stop>\\n              <stop offset=\\"1\\" stop-color=\\"rgba(6,182,212,0.14)\\"></stop>\\n            </linearGradient>\\n            <linearGradient id=\\"g2\\" x1=\\"0\\" x2=\\"1\\">\\n              <stop offset=\\"0\\" stop-color=\\"rgba(5,150,105,0.16)\\"></stop>\\n              <stop offset=\\"1\\" stop-color=\\"rgba(124,58,237,0.14)\\"></stop>\\n            </linearGradient>\\n          </defs>\\n\\n          <rect x=\\"15\\" y=\\"16\\" width=\\"455\\" height=\\"178\\" rx=\\"16\\" fill=\\"url(#g1)\\" stroke=\\"rgba(15,23,42,0.14)\\"></rect>\\n          <text x=\\"34\\" y=\\"44\\" font-size=\\"16\\" font-weight=\\"800\\" fill=\\"#0b2a4a\\">Bagging (Random Forest style)</text>\\n          <text x=\\"34\\" y=\\"70\\" font-size=\\"13\\" fill=\\"#0b2a4a\\">Trees trained independently (can run in parallel)</text>\\n\\n          \x3c!-- bagging trees --\x3e\\n          <g transform=\\"translate(35,88)\\">\\n            <rect x=\\"0\\" y=\\"0\\" width=\\"60\\" height=\\"58\\" rx=\\"12\\" fill=\\"rgba(255,255,255,0.75)\\" stroke=\\"rgba(15,23,42,0.15)\\"></rect>\\n            <text x=\\"10\\" y=\\"34\\" font-size=\\"12\\" font-weight=\\"800\\" fill=\\"#0b2a4a\\">Tree 1</text>\\n\\n            <rect x=\\"72\\" y=\\"0\\" width=\\"60\\" height=\\"58\\" rx=\\"12\\" fill=\\"rgba(255,255,255,0.75)\\" stroke=\\"rgba(15,23,42,0.15)\\"></rect>\\n            <text x=\\"82\\" y=\\"34\\" font-size=\\"12\\" font-weight=\\"800\\" fill=\\"#0b2a4a\\">Tree 2</text>\\n\\n            <rect x=\\"144\\" y=\\"0\\" width=\\"60\\" height=\\"58\\" rx=\\"12\\" fill=\\"rgba(255,255,255,0.75)\\" stroke=\\"rgba(15,23,42,0.15)\\"></rect>\\n            <text x=\\"154\\" y=\\"34\\" font-size=\\"12\\" font-weight=\\"800\\" fill=\\"#0b2a4a\\">Tree 3</text>\\n\\n            <rect x=\\"216\\" y=\\"0\\" width=\\"60\\" height=\\"58\\" rx=\\"12\\" fill=\\"rgba(255,255,255,0.75)\\" stroke=\\"rgba(15,23,42,0.15)\\"></rect>\\n            <text x=\\"226\\" y=\\"34\\" font-size=\\"12\\" font-weight=\\"800\\" fill=\\"#0b2a4a\\">Tree 4</text>\\n\\n            <text x=\\"286\\" y=\\"34\\" font-size=\\"22\\" font-weight=\\"900\\" fill=\\"#0b2a4a\\">\u2192</text>\\n            <rect x=\\"314\\" y=\\"-2\\" width=\\"105\\" height=\\"62\\" rx=\\"14\\" fill=\\"rgba(255,255,255,0.82)\\" stroke=\\"rgba(15,23,42,0.18)\\"></rect>\\n            <text x=\\"328\\" y=\\"26\\" font-size=\\"12\\" font-weight=\\"900\\" fill=\\"#0b2a4a\\">Average /</text>\\n            <text x=\\"328\\" y=\\"44\\" font-size=\\"12\\" font-weight=\\"900\\" fill=\\"#0b2a4a\\">Vote</text>\\n          </g>\\n\\n          <rect x=\\"510\\" y=\\"16\\" width=\\"455\\" height=\\"178\\" rx=\\"16\\" fill=\\"url(#g2)\\" stroke=\\"rgba(15,23,42,0.14)\\"></rect>\\n          <text x=\\"529\\" y=\\"44\\" font-size=\\"16\\" font-weight=\\"800\\" fill=\\"#0b2a4a\\">Boosting (AdaBoost / XGBoost style)</text>\\n          <text x=\\"529\\" y=\\"70\\" font-size=\\"13\\" fill=\\"#0b2a4a\\">Trees trained sequentially (each corrects previous errors)</text>\\n\\n          \x3c!-- boosting chain --\x3e\\n          <g transform=\\"translate(525,92)\\">\\n            <rect x=\\"0\\" y=\\"0\\" width=\\"68\\" height=\\"55\\" rx=\\"12\\" fill=\\"rgba(255,255,255,0.75)\\" stroke=\\"rgba(15,23,42,0.15)\\"></rect>\\n            <text x=\\"12\\" y=\\"33\\" font-size=\\"12\\" font-weight=\\"800\\" fill=\\"#0b2a4a\\">Tree 1</text>\\n\\n            <text x=\\"72\\" y=\\"35\\" font-size=\\"20\\" font-weight=\\"900\\" fill=\\"#0b2a4a\\">\u2192</text>\\n\\n            <rect x=\\"92\\" y=\\"0\\" width=\\"68\\" height=\\"55\\" rx=\\"12\\" fill=\\"rgba(255,255,255,0.75)\\" stroke=\\"rgba(15,23,42,0.15)\\"></rect>\\n            <text x=\\"104\\" y=\\"33\\" font-size=\\"12\\" font-weight=\\"800\\" fill=\\"#0b2a4a\\">Tree 2</text>\\n\\n            <text x=\\"164\\" y=\\"35\\" font-size=\\"20\\" font-weight=\\"900\\" fill=\\"#0b2a4a\\">\u2192</text>\\n\\n            <rect x=\\"184\\" y=\\"0\\" width=\\"68\\" height=\\"55\\" rx=\\"12\\" fill=\\"rgba(255,255,255,0.75)\\" stroke=\\"rgba(15,23,42,0.15)\\"></rect>\\n            <text x=\\"196\\" y=\\"33\\" font-size=\\"12\\" font-weight=\\"800\\" fill=\\"#0b2a4a\\">Tree 3</text>\\n\\n            <text x=\\"256\\" y=\\"35\\" font-size=\\"20\\" font-weight=\\"900\\" fill=\\"#0b2a4a\\">\u2192</text>\\n\\n            <rect x=\\"280\\" y=\\"0\\" width=\\"150\\" height=\\"55\\" rx=\\"12\\" fill=\\"rgba(255,255,255,0.82)\\" stroke=\\"rgba(15,23,42,0.18)\\"></rect>\\n            <text x=\\"293\\" y=\\"24\\" font-size=\\"12\\" font-weight=\\"900\\" fill=\\"#0b2a4a\\">Add weighted</text>\\n            <text x=\\"293\\" y=\\"42\\" font-size=\\"12\\" font-weight=\\"900\\" fill=\\"#0b2a4a\\">contributions</text>\\n          </g>\\n        </svg>\\n      </div>\\n    </section>\\n\\n    \x3c!-- 2) Decision Trees --\x3e\\n    <section id=\\"trees\\">\\n      <h2 id=\\"2-decision-trees-how-they-learn-foundation\\">2) Decision Trees: How They Learn <span class=\\"tag\\">Foundation</span></h2>\\n\\n      <div class=\\"grid cols2\\">\\n        <div class=\\"card\\">\\n          <h3 id=\\"what-a-split-really-is\\">What a split really is</h3>\\n          <p>\\n            At a node, a decision tree searches for a question like:\\n            <span class=\\"math\\">$\\\\text{feature}_j \\\\le \\\\text{threshold}$</span>\\n            that divides the data into two groups (left/right).\\n          </p>\\n          <p>\\n            The tree wants the children nodes to be <strong>more \u201cpure\u201d</strong> than the parent \u2014\\n            meaning each child contains mostly one class (for classification),\\n            or reduced spread (for regression).\\n          </p>\\n        </div>\\n\\n        <div class=\\"card\\">\\n          <h3 id=\\"the-tree-s-greedy-rule\\">The tree\u2019s \u201cgreedy\u201d rule</h3>\\n          <p>\\n            Trees usually use a greedy strategy:\\n            <strong>pick the best split right now</strong>,\\n            then repeat inside each child node.\\n          </p>\\n          <div class=\\"callout amber\\">\\n            Greedy means: it doesn\u2019t look ahead many steps; it chooses the best local improvement.\\n            That\u2019s why trees are fast and intuitive \u2014 but also why a single tree can be unstable.\\n          </div>\\n        </div>\\n      </div>\\n\\n      <details>\\n        <summary>Optional: what does \u201cbest\u201d mean in practice?</summary>\\n        <p>\\n          \u201cBest\u201d means the split that most reduces a chosen impurity measure (Gini/Entropy),\\n          or for modern boosting (XGBoost) the split that most reduces the training loss (objective).\\n          The spirit is identical: <strong>choose the split that creates the most useful separation</strong>.\\n        </p>\\n      </details>\\n    </section>\\n\\n    \x3c!-- 3) Impurity --\x3e\\n    <section id=\\"impurity\\">\\n      <h2 id=\\"3-impurity-measures-gini-and-information-gain-splitting-criteria\\">3) Impurity Measures: Gini and Information Gain <span class=\\"tag\\">Splitting Criteria</span></h2>\\n\\n      <div class=\\"callout violet\\">\\n        <strong>Impurity</strong> is a number that tells you how mixed the classes are inside a node.\\n        Lower impurity = node is closer to \u201call one class\u201d.\\n      </div>\\n\\n      <div class=\\"grid cols2\\">\\n        <div class=\\"card\\">\\n          <h3 id=\\"gini-impurity-cart-very-common\\">Gini Impurity (CART; very common)</h3>\\n          <p><strong>Idea:</strong> if a node is mostly one class, it\u2019s pure; if it\u2019s evenly mixed, it\u2019s impure.</p>\\n          <div class=\\"math\\">\\n            $$\\\\mathrm{Gini}(\\\\text{node}) = 1 - \\\\sum_k p_k^2$$\\n          </div>\\n          <ul>\\n            <li>Binary example: if p = 0.7 and 0.3 \u2192 Gini = 1 \u2212 (0.49 + 0.09) = 0.42</li>\\n            <li>Pure node: p = 1.0 and 0.0 \u2192 Gini = 0</li>\\n          </ul>\\n        </div>\\n\\n        <div class=\\"card\\">\\n          <h3 id=\\"entropy-and-information-gain-id3-c4-5-style\\">Entropy &amp; Information Gain (ID3/C4.5 style)</h3>\\n          <p><strong>Idea:</strong> entropy measures \u201csurprise\u201d or uncertainty in the class label.</p>\\n          <div class=\\"math\\">\\n            $$\\\\mathrm{Entropy}(\\\\text{node}) = -\\\\sum_k p_k\\\\,\\\\log_2(p_k)$$\\n          </div>\\n          <p>\\n            A split is chosen by maximizing Information Gain:\\n          </p>\\n          <div class=\\"math\\">\\n            $$IG = \\\\mathrm{Entropy}(\\\\text{parent}) - \\\\left(\\\\frac{N_L}{N}\\\\,\\\\mathrm{Entropy}(L) + \\\\frac{N_R}{N}\\\\,\\\\mathrm{Entropy}(R)\\\\right)$$\\n          </div>\\n        </div>\\n      </div>\\n\\n      <div class=\\"callout green\\">\\n        <strong>How the tree uses impurity:</strong><br>\\n        For each candidate split, compute the children impurities, take a weighted average,\\n        then choose the split with the <strong>largest impurity reduction</strong>.\\n      </div>\\n\\n      <details>\\n        <summary>Gini reduction formula (same shape as Information Gain)</summary>\\n        <div class=\\"math\\">\\n          $$\\\\mathrm{GiniSplit} = \\\\frac{N_L}{N}\\\\,\\\\mathrm{Gini}(L) + \\\\frac{N_R}{N}\\\\,\\\\mathrm{Gini}(R) \\\\qquad\\n          \\\\mathrm{GiniGain} = \\\\mathrm{Gini}(\\\\text{parent}) - \\\\mathrm{GiniSplit}$$\\n        </div>\\n      </details>\\n    </section>\\n\\n    \x3c!-- 4) Split example --\x3e\\n    <section id=\\"split-example\\">\\n      <h2 id=\\"4-a-concrete-split-example-step-by-step-intuition\\">4) A Concrete Split Example (Step-by-Step) <span class=\\"tag\\">Intuition</span></h2>\\n\\n      <p>\\n        Imagine a node contains 10 training samples for binary classification (Yes/No):\\n        <strong>6 Yes</strong>, <strong>4 No</strong>.\\n      </p>\\n\\n      <div class=\\"grid cols2\\">\\n        <div class=\\"card\\">\\n          <h3 id=\\"parent-impurity-gini\\">Parent impurity (Gini)</h3>\\n          <p>p(Yes)=0.6, p(No)=0.4</p>\\n          <div class=\\"math\\">\\n            $$\\\\mathrm{Gini}(\\\\text{parent}) = 1 - (0.6^2 + 0.4^2) = 1 - (0.36 + 0.16) = 0.48$$\\n          </div>\\n        </div>\\n\\n        <div class=\\"card\\">\\n          <h3 id=\\"try-a-candidate-split\\">Try a candidate split</h3>\\n          <p>Suppose we test: <span class=\\"math\\">$\\\\text{Age} \\\\le 30$</span></p>\\n          <ul>\\n            <li>Left child: 6 samples \u2192 5 Yes, 1 No</li>\\n            <li>Right child: 4 samples \u2192 1 Yes, 3 No</li>\\n          </ul>\\n        </div>\\n      </div>\\n\\n      <div class=\\"grid cols2\\">\\n        <div class=\\"card\\">\\n          <h3 id=\\"child-impurities\\">Child impurities</h3>\\n          <div class=\\"math\\">\\n            $$\\\\begin{aligned}\\n            \\\\mathrm{Gini}(L) &amp;= 1 - \\\\left(\\\\left(\\\\frac{5}{6}\\\\right)^2 + \\\\left(\\\\frac{1}{6}\\\\right)^2\\\\right) = 1 - \\\\frac{26}{36} = \\\\frac{10}{36} \\\\approx 0.2778 \\\\\\\\\\n            \\\\mathrm{Gini}(R) &amp;= 1 - \\\\left(\\\\left(\\\\frac{1}{4}\\\\right)^2 + \\\\left(\\\\frac{3}{4}\\\\right)^2\\\\right) = 1 - \\\\frac{10}{16} = \\\\frac{6}{16} = 0.375\\n            \\\\end{aligned}$$\\n          </div>\\n        </div>\\n\\n        <div class=\\"card\\">\\n          <h3 id=\\"weighted-average-and-gain\\">Weighted average &amp; gain</h3>\\n          <div class=\\"math\\">\\n            $$\\\\begin{aligned}\\n            \\\\mathrm{GiniSplit} &amp;= \\\\frac{6}{10}\\\\cdot 0.2778 + \\\\frac{4}{10}\\\\cdot 0.375 = 0.3167 \\\\\\\\\\n            \\\\mathrm{GiniGain} &amp;= 0.48 - 0.3167 = 0.1633\\n            \\\\end{aligned}$$\\n          </div>\\n          <p>\\n            The tree would compare this gain with all other possible splits and choose the biggest.\\n          </p>\\n        </div>\\n      </div>\\n\\n      <div class=\\"callout\\">\\n        <strong>Core takeaway:</strong> every split is \u201cjust\u201d computing impurity before and after.\\n        Ensembles (bagging/boosting) change <em>how</em> trees are trained, not the basic logic of splitting.\\n      </div>\\n    </section>\\n\\n    \x3c!-- 5) Bagging --\x3e\\n    <section id=\\"bagging\\">\\n      <h2 id=\\"5-bagging-and-random-forests-variance-reduction\\">5) Bagging and Random Forests <span class=\\"tag\\">Variance Reduction</span></h2>\\n\\n      <div class=\\"grid cols2\\">\\n        <div class=\\"card\\">\\n          <h3 id=\\"bagging-in-plain-words\\">Bagging in plain words</h3>\\n          <p>\\n            Bagging trains many trees on slightly different versions of the dataset.\\n            Each tree makes its own prediction, then we combine predictions by\\n            <strong>averaging</strong> (regression) or <strong>voting</strong> (classification).\\n          </p>\\n          <div class=\\"callout green\\">\\n            Bagging is powerful because averaging many noisy models tends to cancel out random errors.\\n          </div>\\n        </div>\\n\\n        <div class=\\"card\\">\\n          <h3 id=\\"how-do-we-get-different-versions-of-the-data\\">How do we get \u201cdifferent versions\u201d of the data?</h3>\\n          <p>\\n            Using <strong>bootstrap sampling</strong>:\\n            sample N points from the training set <em>with replacement</em>.\\n            Some points repeat, some are missing.\\n          </p>\\n          <ul>\\n            <li>Each tree sees a different dataset \u2192 trees become less correlated.</li>\\n            <li>Less correlation \u2192 averaging works better.</li>\\n          </ul>\\n        </div>\\n      </div>\\n\\n      <h3 id=\\"random-forest-bagging-feature-randomness\\">Random Forest: Bagging + Feature Randomness</h3>\\n      <div class=\\"grid cols2\\">\\n        <div class=\\"card\\">\\n          <p>\\n            Random Forest adds one more trick:\\n            at each split, it considers only a <strong>random subset of features</strong>.\\n          </p>\\n          <ul>\\n            <li>This makes trees even more diverse.</li>\\n            <li>Diversity improves the power of averaging.</li>\\n          </ul>\\n        </div>\\n        <div class=\\"card\\">\\n          <p><strong>What split criterion is used?</strong></p>\\n          <p>\\n            Usually <strong>Gini impurity</strong> for classification (CART-style),\\n            and variance/MSE for regression.\\n          </p>\\n          <div class=\\"callout amber\\">\\n            In Random Forest, trees are independent, so you can train trees in parallel very easily.\\n          </div>\\n        </div>\\n      </div>\\n\\n      <details>\\n        <summary>Common Random Forest terms</summary>\\n        <ul>\\n          <li><strong>n_estimators</strong>: number of trees.</li>\\n          <li><strong>max_features</strong>: how many features to try at each split.</li>\\n          <li><strong>OOB (out-of-bag) error</strong>: estimate accuracy using samples left out of each bootstrap.</li>\\n        </ul>\\n      </details>\\n    </section>\\n\\n    \x3c!-- 6) Boosting overview --\x3e\\n    <section id=\\"boosting\\">\\n      <h2 id=\\"6-boosting-overview-bias-reduction\\">6) Boosting Overview <span class=\\"tag\\">Bias Reduction</span></h2>\\n\\n      <div class=\\"callout\\">\\n        <strong>Boosting</strong> trains trees one after another.\\n        Each new tree is trained to correct mistakes made by the current ensemble.\\n      </div>\\n\\n      <div class=\\"grid cols2\\">\\n        <div class=\\"card\\">\\n          <h3 id=\\"boosting-as-learning-from-errors\\">Boosting as \u201clearning from errors\u201d</h3>\\n          <p>\\n            Suppose the first model is a little better than random.\\n            It will still make mistakes on \u201chard\u201d examples.\\n            Boosting increases focus on those hard examples, so the next model improves where it matters.\\n          </p>\\n          <p>\\n            Over many rounds, the ensemble becomes very strong.\\n          </p>\\n        </div>\\n\\n        <div class=\\"card\\">\\n          <h3 id=\\"two-major-boosting-styles\\">Two major boosting styles</h3>\\n          <ul>\\n            <li><strong>AdaBoost</strong>: reweights training examples; uses a weighted vote.</li>\\n            <li><strong>Gradient Boosting / XGBoost</strong>: minimizes a loss function using gradients; adds trees as corrections.</li>\\n          </ul>\\n          <div class=\\"callout amber\\">\\n            Boosting is sequential at the \u201ctree level\u201d: tree (t) depends on results from tree (t\u22121).\\n          </div>\\n        </div>\\n      </div>\\n    </section>\\n\\n    \x3c!-- 7) AdaBoost --\x3e\\n    <section id=\\"adaboost\\">\\n      <h2 id=\\"7-adaboost-adaptive-boosting-deep-dive-weights-weak-learners\\">7) AdaBoost (Adaptive Boosting) \u2014 Deep Dive <span class=\\"tag\\">Weights + Weak Learners</span></h2>\\n\\n      <div class=\\"callout violet\\">\\n        AdaBoost is easiest to understand if you imagine the algorithm is \u201cturning up the volume\u201d on points it got wrong.\\n        Those points become more important in the next round.\\n      </div>\\n\\n      <h3 id=\\"what-adaboost-uses-as-base-learners\\">What AdaBoost uses as base learners</h3>\\n      <div class=\\"grid cols2\\">\\n        <div class=\\"card\\">\\n          <p>\\n            Most commonly: <strong>decision stumps</strong> (depth-1 trees).\\n            A stump is one split like:\\n            <span class=\\"math\\">$\\\\text{feature}_j \\\\le \\\\text{threshold}$</span>.\\n          </p>\\n          <p>\\n            A stump is weak by itself, but many stumps combined can form a complex boundary.\\n          </p>\\n        </div>\\n        <div class=\\"card\\">\\n          <p>\\n            AdaBoost is typically described for binary labels:\\n            <span class=\\"math\\">$y \\\\in \\\\{-1, +1\\\\}$</span>.\\n            (It can be extended, but binary is the cleanest story.)\\n          </p>\\n        </div>\\n      </div>\\n\\n      <h3 id=\\"adaboost-algorithm-step-by-step\\">AdaBoost algorithm (step-by-step)</h3>\\n      <pre class=\\"code\\">Initialize weights: w_i = 1/N for i=1..N\\n\\nFor t = 1..T:\\n  1) Train weak learner h_t(x) using weights w_i\\n  2) Compute weighted error:\\n       \u03b5_t = \u03a3 w_i * 1[y_i \u2260 h_t(x_i)]\\n  3) Compute learner weight (importance):\\n       \u03b1_t = 0.5 * ln( (1 \u2212 \u03b5_t) / \u03b5_t )\\n  4) Update sample weights:\\n       w_i \u2190 w_i * exp( \u2212\u03b1_t * y_i * h_t(x_i) )\\n     (misclassified points get upweighted)\\n  5) Normalize weights so \u03a3 w_i = 1\\n\\nFinal prediction:\\n  H(x) = sign( \u03a3 \u03b1_t * h_t(x) )\\n      </pre>\\n\\n      <div class=\\"grid cols2\\">\\n        <div class=\\"card\\">\\n          <h3 id=\\"what-does-mean\\">What does \u03b1 mean?</h3>\\n          <p>\\n            <strong>\u03b1<sub>t</sub></strong> is how much we trust the stump.\\n            If a stump has low error, it gets a larger \u03b1 (more voting power).\\n          </p>\\n          <div class=\\"math\\">\\n            $$\\\\alpha_t = \\\\tfrac{1}{2}\\\\ln\\\\left(\\\\frac{1-\\\\varepsilon_t}{\\\\varepsilon_t}\\\\right)$$\\n          </div>\\n        </div>\\n\\n        <div class=\\"card\\">\\n          <h3 id=\\"why-weights-focus-on-mistakes\\">Why weights focus on mistakes</h3>\\n          <p>\\n            If a point is misclassified, the term\\n            <span class=\\"math\\">$\\\\exp(-\\\\alpha\\\\, y\\\\, h(x))$</span>\\n            becomes <strong>exp(+\u03b1)</strong>, increasing its weight.\\n            Correct points shrink by <strong>exp(\u2212\u03b1)</strong>.\\n          </p>\\n          <div class=\\"callout amber\\">\\n            This is why AdaBoost can be sensitive to noise/outliers:\\n            if an outlier is repeatedly misclassified, its weight can become huge.\\n          </div>\\n        </div>\\n      </div>\\n\\n      <h3 id=\\"how-splitting-impurity-works-inside-adaboost\\">How splitting/impurity works inside AdaBoost</h3>\\n      <div class=\\"callout green\\">\\n        AdaBoost changes the \u201cimportance\u201d of each training sample via weights.\\n        That means when the stump chooses a split, it effectively uses a <strong>weighted impurity</strong> (or weighted classification error).\\n      </div>\\n\\n      <details>\\n        <summary>Weighted Gini idea (intuition)</summary>\\n        <p>\\n          In a normal node, class probability is \u201ccount of class / total count\u201d.\\n          In AdaBoost, it becomes \u201csum of weights of class / sum of all weights\u201d.\\n        </p>\\n        <div class=\\"math\\">\\n          $$p_k = \\\\frac{\\\\sum_i w_i\\\\,\\\\mathbf{1}[y_i = k]}{\\\\sum_i w_i} \\\\qquad\\n          \\\\mathrm{WeightedGini} = 1 - \\\\sum_k p_k^2$$\\n        </div>\\n        <p>\\n          The stump still tries to reduce impurity \u2014 but now mistakes have larger weights,\\n          so splits that fix mistakes become more attractive.\\n        </p>\\n      </details>\\n\\n      <details>\\n        <summary>Mini numeric example (why a weak learner can get high \u03b1)</summary>\\n        <p>\\n          If \u03b5 = 0.2 (20% weighted error), then:\\n        </p>\\n        <div class=\\"math\\">\\n          $$\\\\alpha = \\\\tfrac{1}{2}\\\\ln\\\\left(\\\\frac{0.8}{0.2}\\\\right) = \\\\tfrac{1}{2}\\\\ln(4) \\\\approx 0.693$$\\n        </div>\\n        <p>\\n          That\u2019s a strong positive weight, meaning the stump gets a meaningful vote.\\n          If \u03b5 approaches 0.5, \u03b1 approaches 0 (weak vote).\\n        </p>\\n      </details>\\n    </section>\\n\\n    \x3c!-- 8) XGBoost --\x3e\\n    <section id=\\"xgboost\\">\\n      <h2 id=\\"8-gradient-boosting-and-xgboost-loss-optimization\\">8) Gradient Boosting and XGBoost <span class=\\"tag\\">Loss Optimization</span></h2>\\n\\n      <div class=\\"callout\\">\\n        <strong>Gradient Boosting</strong> generalizes boosting by saying:\\n        \u201cLet\u2019s minimize a loss function (objective) by adding trees that move us in the best direction.\u201d\\n      </div>\\n\\n      <h3 id=\\"gradient-boosting-idea-in-simple-steps\\">Gradient Boosting idea in simple steps</h3>\\n      <div class=\\"grid cols2\\">\\n        <div class=\\"card\\">\\n          <ol>\\n            <li>Start with a simple prediction (like the average).</li>\\n            <li>Compute how wrong you are (residuals / gradients).</li>\\n            <li>Train a small tree to predict those errors.</li>\\n            <li>Add the tree (scaled by a learning rate) to improve predictions.</li>\\n            <li>Repeat.</li>\\n          </ol>\\n        </div>\\n        <div class=\\"card\\">\\n          <p><strong>Additive model view:</strong></p>\\n          <div class=\\"math\\">\\n            $$\\\\hat{y}^{(t)}(x) = \\\\hat{y}^{(t-1)}(x) + \\\\eta\\\\, f_t(x)$$\\n          </div>\\n          <p>\\n            Here <strong>\u03b7</strong> is the learning rate (shrinkage).\\n            Smaller \u03b7 usually needs more trees but improves generalization.\\n          </p>\\n        </div>\\n      </div>\\n\\n      <div class=\\"callout amber\\">\\n        <strong>Regression vs classification nuance:</strong>\\n        for squared-error regression, the \u201cerrors\u201d are literal residuals.\\n        For logistic loss and other objectives, boosting fits negative\\n        gradients (pseudo-residuals), not raw label errors.\\n      </div>\\n\\n      <h3 id=\\"what-makes-xgboost-special\\">What makes XGBoost special?</h3>\\n      <div class=\\"grid cols3\\">\\n        <div class=\\"card\\">\\n          <p><strong>Second-order optimization</strong></p>\\n          <p>\\n            Uses gradients (g) <em>and</em> Hessians (h) to choose better splits.\\n          </p>\\n          <span class=\\"badge\\"><span class=\\"v v\\"></span> More accurate split scoring</span>\\n        </div>\\n        <div class=\\"card\\">\\n          <p><strong>Regularization</strong></p>\\n          <p>\\n            Penalizes complex trees to reduce overfitting.\\n            (Think: don\u2019t let the model become \u201ctoo wiggly\u201d.)\\n          </p>\\n          <span class=\\"badge\\"><span class=\\"a a\\"></span> Better generalization</span>\\n        </div>\\n        <div class=\\"card\\">\\n          <p><strong>Engineering for speed</strong></p>\\n          <p>\\n            Histogram splits, cache efficiency, parallel computation, GPU support, distributed training.\\n          </p>\\n          <span class=\\"badge\\"><span class=\\"g g\\"></span> Much faster on large data</span>\\n        </div>\\n      </div>\\n\\n      <h3 id=\\"how-does-xgboost-decide-splits-vs-gini-entropy\\">How does XGBoost decide splits (vs Gini/Entropy)?</h3>\\n      <div class=\\"callout violet\\">\\n        Random Forest uses <strong>impurity reduction</strong> (Gini/Entropy).<br>\\n        XGBoost uses <strong>objective reduction</strong> (loss + regularization).<br><br>\\n        But conceptually, both are choosing the split that gives the \u201cbest improvement\u201d.\\n      </div>\\n\\n      <details>\\n        <summary>Split \u201cgain\u201d intuition (no heavy math)</summary>\\n        <p>\\n          For a candidate split, XGBoost summarizes the node using two numbers:\\n          the sum of gradients (G) and sum of Hessians (H) in that node.\\n          It estimates how much the regularized objective improves if we split into left and right.\\n        </p>\\n        <div class=\\"math\\">\\n          $$\\\\mathrm{Gain} =\\n          \\\\frac{1}{2}\\\\left[\\n          \\\\frac{G_L^2}{H_L+\\\\lambda} +\\n          \\\\frac{G_R^2}{H_R+\\\\lambda} -\\n          \\\\frac{(G_L+G_R)^2}{H_L+H_R+\\\\lambda}\\n          \\\\right] - \\\\gamma$$\\n        </div>\\n        <p>\\n          Where \u03bb is L2 regularization on leaf weights and \u03b3 is a penalty for creating a new split\\n          (discouraging unnecessary splits).\\n        </p>\\n      </details>\\n\\n      <details>\\n        <summary>Parallel-friendly split finding (histograms)</summary>\\n        <p>\\n          XGBoost often uses a histogram algorithm:\\n        </p>\\n        <ul>\\n          <li>Bucket each feature into bins (like 256 bins).</li>\\n          <li>Accumulate gradient/Hessian sums per bin.</li>\\n          <li>Scan bins to find the best threshold.</li>\\n        </ul>\\n        <p>\\n          This makes split-finding fast and parallelizable across features and bins.\\n        </p>\\n      </details>\\n    </section>\\n\\n    \x3c!-- 9) Sequential vs Parallel --\x3e\\n    <section id=\\"parallel\\">\\n      <h2 id=\\"9-sequential-vs-parallel-in-boosting-xgboost-important-detail\\">9) Sequential vs Parallel in Boosting (XGBoost) <span class=\\"tag\\">Important Detail</span></h2>\\n\\n      <div class=\\"callout amber\\">\\n        <strong>Boosting is sequential across trees</strong> because tree t needs the gradients/residuals from the current model (trees 1..t\u22121).\\n        So you can\u2019t train all trees at once.\\n      </div>\\n\\n      <h3 id=\\"so-how-can-xgboost-still-be-fast\\">So how can XGBoost still be fast?</h3>\\n      <p>\\n        Because XGBoost parallelizes <strong>within each boosting round</strong>.\\n        Think: \u201cWe can\u2019t write Chapter 5 before Chapter 4, but many people can work in parallel on Chapter 4.\u201d\\n      </p>\\n\\n      <div class=\\"grid cols2\\">\\n        <div class=\\"card\\">\\n          <h3 id=\\"what-can-be-parallelized-inside-a-round\\">What can be parallelized inside a round?</h3>\\n          <ul>\\n            <li><strong>Gradient &amp; Hessian computation</strong> per data point (independent operations).</li>\\n            <li><strong>Split search across features</strong> (each feature can be evaluated separately).</li>\\n            <li><strong>Histogram building</strong> (bin counts/aggregations can be parallelized).</li>\\n            <li><strong>Node processing at the same depth</strong> (level-wise growth enables parallel node expansion).</li>\\n          </ul>\\n        </div>\\n\\n        <div class=\\"card\\">\\n          <h3 id=\\"distributed-multi-gpu-idea\\">Distributed / multi-GPU idea</h3>\\n          <ul>\\n            <li>Each worker computes local gradient statistics.</li>\\n            <li>Workers do a <strong>reduce</strong> (sum) to combine stats.</li>\\n            <li>Then the best split is chosen globally.</li>\\n          </ul>\\n          <div class=\\"callout green\\">\\n            Trees stay sequential, but the expensive computations inside each tree are distributed.\\n          </div>\\n        </div>\\n      </div>\\n\\n      <details>\\n        <summary>What XGBoost does NOT parallelize</summary>\\n        <ul>\\n          <li>Training tree (t+1) before finishing tree (t)</li>\\n          <li>Skipping gradient dependency (that would break boosting)</li>\\n        </ul>\\n      </details>\\n    </section>\\n\\n    \x3c!-- 10) Comparison --\x3e\\n    <section id=\\"compare\\">\\n      <h2 id=\\"10-random-forest-vs-xgboost-practical-comparison\\">10) Random Forest vs XGBoost <span class=\\"tag\\">Practical Comparison</span></h2>\\n\\n      <table>\\n        <tbody><tr>\\n          <th>Aspect</th>\\n          <th>Random Forest (Bagging)</th>\\n          <th>XGBoost (Boosting)</th>\\n        </tr>\\n        <tr>\\n          <td><strong>Training style</strong></td>\\n          <td>Independent trees (parallel)</td>\\n          <td>Sequential trees (each corrects errors)</td>\\n        </tr>\\n        <tr>\\n          <td><strong>Main benefit</strong></td>\\n          <td>Reduces variance, very robust</td>\\n          <td>Reduces bias strongly, often best accuracy</td>\\n        </tr>\\n        <tr>\\n          <td><strong>Split criterion</strong></td>\\n          <td>Gini / Entropy (classification) or MSE (regression)</td>\\n          <td>Objective gain using gradients &amp; Hessians + regularization</td>\\n        </tr>\\n        <tr>\\n          <td><strong>Noise sensitivity</strong></td>\\n          <td>Usually more tolerant</td>\\n          <td>More sensitive; needs regularization/tuning</td>\\n        </tr>\\n        <tr>\\n          <td><strong>Hyperparameters</strong></td>\\n          <td>Fewer critical knobs</td>\\n          <td>More knobs; more control (and more tuning)</td>\\n        </tr>\\n        <tr>\\n          <td><strong>Parallelism</strong></td>\\n          <td>Across trees</td>\\n          <td>Within each tree / round (features, bins, nodes)</td>\\n        </tr>\\n      </tbody></table>\\n\\n      <div class=\\"callout\\">\\n        <strong>Rule of thumb:</strong>\\n        If you want a strong baseline with little tuning, Random Forest is great.\\n        If you want maximum performance on tabular data and can tune/regularize, XGBoost often wins.\\n      </div>\\n    </section>\\n\\n    \x3c!-- 11) Cheat sheet --\x3e\\n    <section id=\\"cheatsheet\\">\\n      <h2 id=\\"11-quick-cheat-sheet-remember-fast\\">11) Quick Cheat Sheet <span class=\\"tag\\">Remember Fast</span></h2>\\n\\n      <div class=\\"grid cols2\\">\\n        <div class=\\"card\\">\\n          <h3 id=\\"bagging-random-forest\\">Bagging (Random Forest)</h3>\\n          <ul>\\n            <li><strong>Goal:</strong> reduce variance.</li>\\n            <li><strong>How:</strong> bootstrap samples + random feature subsets.</li>\\n            <li><strong>Combine:</strong> vote / average.</li>\\n            <li><strong>Splits:</strong> Gini/Entropy (classification).</li>\\n            <li><strong>Parallel:</strong> yes, across trees.</li>\\n          </ul>\\n        </div>\\n\\n        <div class=\\"card\\">\\n          <h3 id=\\"boosting-adaboost-xgboost\\">Boosting (AdaBoost / XGBoost)</h3>\\n          <ul>\\n            <li><strong>Goal:</strong> reduce bias by fixing errors.</li>\\n            <li><strong>AdaBoost:</strong> reweight samples; weighted vote with \u03b1.</li>\\n            <li><strong>Gradient Boosting:</strong> fit residuals/gradients; add trees.</li>\\n            <li><strong>XGBoost:</strong> optimized objective + regularization + fast splits.</li>\\n            <li><strong>Parallel:</strong> not across trees, but inside each round.</li>\\n          </ul>\\n        </div>\\n      </div>\\n\\n      <div class=\\"callout rose\\">\\n        <strong>If you only remember one thing:</strong><br>\\n        Trees split by reducing \u201cbadness\u201d (impurity or loss).<br>\\n        Bagging improves stability by averaging many independent trees.<br>\\n        Boosting improves accuracy by sequentially correcting mistakes.\\n      </div>\\n\\n      <p style=\\"margin-top:16px;\\">\\n        Jump back to the top: <a href=\\"#top\\">\u2191</a>\\n      </p>\\n    </section>\\n\\n    <footer>\\n      This chapter closes the classical tabular-model path and prepares the\\n      transition to learned representations in Part V.\\n    </footer>\\n  </div>"}'),l={title:"Bagging & Boosting (AdaBoost + XGBoost) \u2014 Trees, Impurities, and How Splits Work",slug:"/part4-ml-foundations/05-trees-bagging-boosting",description:"This page is a complete, friendly walkthrough of what we discussed: how decision trees split using Gini impurity and Information Gain, how Bagging (Random Forests) works, how Boosting works, a deep step-by-step of Ada...",sidebar_label:"5. Trees, bagging, and boosting",pagination_label:"5. Trees, bagging, and boosting",hide_title:!0,hide_table_of_contents:!0},d=void 0,g={},c=[];function p(n){return(0,s.jsx)(o.A,{content:r})}function h(n={}){const{wrapper:e}={...(0,a.R)(),...n.components};return e?(0,s.jsx)(e,{...n,children:(0,s.jsx)(p,{...n})}):p()}}}]);